import sys
import re


def is_numeric_cell(cell):
    if not cell:
        return False
    stripped = cell.strip()
    return re.fullmatch(r"^-?\d+(\.\d+)?$", stripped) is not None


def main():
    rows = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        cells = [cell.strip() for cell in line.split("|")]
        rows.append(cells)

    if not rows:
        return

    # Determine column widths
    num_columns = len(rows[0]) if rows else 0
    widths = [0] * num_columns

    # Compute max width for each column
    for row in rows:
        for i in range(num_columns):
            if i >= len(row):
                row.append("")
            cell = row[i].strip()
            widths[i] = max(widths[i], len(cell))

    # Ensure minimum width of 1
    for i in range(num_columns):
        widths[i] = max(widths[i], 1)

    # Determine if each column is numeric
    is_numeric = [False] * num_columns
    for col_idx in range(num_columns):
        numeric = False
        for row_idx in range(len(rows)):
            cell = rows[row_idx][col_idx].strip()
            if cell and is_numeric_cell(cell):
                numeric = True
                break
        is_numeric[col_idx] = numeric

    # Format each row
    def fmt(row):
        cells = []
        for i, cell in enumerate(row):
            cell = cell.strip()
            width = widths[i]
            if is_numeric[i] and cell:
                padding = " " * (width - len(cell))
                cells.append(cell + padding)
            else:
                padding = " " * (width - len(cell))
                cells.append(padding + cell)
        return " | ".join(cells)

    # Print header
    header_row = rows[0]
    print(fmt(header_row))

    # Print separator
    print("-+-".join("-" * w for w in widths))

    # Print data rows
    for row in rows[1:]:
        print(fmt(row))


if __name__ == "__main__":
    main()
